// 位置结构，用于用户和洛共用
const LocationSchema = z.object({
    区域: z.string().prefault('金穗平原'),
    地点: z.string().prefault('小树林'),
    具体建筑: z.string().prefault('无'),
}).prefault({});
// 角色生存状态，用于用户和洛共用
const SurvivalSchema = z.object({
    饱腹度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(80),
    疲劳度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(20),
    清洁度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(90),
    当前位置: LocationSchema,
});
export const Schema = z.object({
    角色: z.object({
        用户: SurvivalSchema.prefault({}),
        洛: SurvivalSchema.extend({
            好感度: z.coerce.number().transform(v => _.clamp(v, -100, 101)).prefault(0),
        }).prefault({}),
    }).prefault({}),
    世界: z.object({
        时间: z.string().prefault('清晨 (第一天)'),
        天气: z.string().prefault('晴朗'),
        声望: z.record(z.string().describe('区域名'), z.coerce.number().transform(v => _.clamp(v, -100, 100))).prefault({}),
        地点误解等级: z.record(z.string().describe('地点名'), z.coerce.number().transform(v => _.clamp(v, 0, 100))).prefault({}),
        事件状态: z.record(z.string().describe('事件名'), z.coerce.number()).prefault({}),
    }).prefault({}),
    元素契约: z.object({
        当前债务: z.record(z.string().describe('精灵名'), z.object({
            偿还任务: z.string(),
            剩余天数: z.coerce.number(),
        })).transform(data => _.pickBy(data, ({ 剩余天数 }) => 剩余天数 > 0)).prefault({}),
    }).prefault({}),
});
